-- Seed idempotent de la table `features` (SRD 5.1 FR, AideDD).
begin;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('artificier-bricoleur', 'Bricoleur', 'classe', 'Artificier', NULL, NULL, 'Vous maîtrisez les outils de bricoleur. En utilisant ces outils, vous pouvez passer 1 heure et dépenser pour 10 po de matériaux pour construire un mécanisme de taille TP, de CA 5 et 1 pv. Le dispositif cesse de fonctionner après 24 heures (sauf si vous passez 1 heure à le réparer) ou si vous utilisez une action pour le démonter ; à ce moment, vous pouvez récupérer les matériaux que vous avez utilisés pour le créer. Vous pouvez avoir jusqu''à trois de ces dispositifs actifs à la fois. Lorsque vous créez un mécanisme, choisissez l''une des options suivantes : Allume feu (le mécanisme produit une toute petite flamme qui peut être utilisée pour allumer une bougie ou une torche au prix d''une action), Boîte à musique (lorsqu''on l''ouvre, la boîte reproduit une chanson à un volume modéré jusqu''à la fin du morceau ou avant si la boîte est refermée), Jouet mécanique (le jouet représente un animal ou une personne sur des roulettes, se déplace de 1,50 mètre chaque tour dans une direction aléatoire et fait des bruits en fonction de la créature qu''il représente).')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-defense-sans-armure', 'Défense sans armure', 'classe', 'Barbare', NULL, 1, 'Tant que vous ne portez pas d''armure, votre classe d''armure est égale à 10 + votre modificateur de Dextérité + votre modificateur de Constitution.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-rage', 'Rage', 'classe', 'Barbare', NULL, 1, 'En combat, vous vous battez avec une férocité bestiale. Durant votre tour, vous pouvez entrer en rage en utilisant une action bonus. En rage, vous gagnez les bénéfices suivants si vous ne portez pas d''armure lourde : Vous avez un avantage aux jets de Force et aux jets de sauvegarde de Force. Quand vous effectuez une attaque au corps à corps avec une arme utilisant la Force, vous gagnez un bonus aux jets de dégâts qui dépend de votre niveau de barbare, comme indiqué dans la colonne Dégâts de la table. Vous avez la résistance aux dégâts contondants, perforants et tranchants. Si vous êtes capable de lancer des sorts, vous ne pouvez les lancer ou vous concentrer sur eux pour toute la durée de la rage. Votre rage dure 1 minute. Elle finit prématurément si vous devenez inconscient, ou si votre tour se termine et que vous n''avez ni attaqué une créature hostile, ni subi des dégâts, depuis votre précédent tour. Vous pouvez également mettre fin à votre rage durant votre tour par une action bonus. Vous récupérez les utilisations de rage dépensées après avoir terminé un repos long.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-attaque-temeraire', 'Attaque téméraire', 'classe', 'Barbare', NULL, 2, 'À partir du niveau 2, vous pouvez mettre de côté votre défense pour attaquer avec toute la violence du désespoir. Lorsque vous effectuez la première attaque de votre tour, vous pouvez décider d''effectuer une Attaque téméraire. Vous obtenez ainsi un avantage aux jets d''attaque au corps à corps avec une arme utilisant la Force durant ce tour, mais les attaques effectuées contre vous ont également un avantage jusqu''à votre prochain tour.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-sens-du-danger', 'Sens du danger', 'classe', 'Barbare', NULL, 2, 'Au niveau 2, vous ressentez une sensation étrange lorsque les choses qui vous entourent ne sont pas comme elles devraient être, vous donnant un avantage lorsque vous tentez de vous extirper du danger. Vous avez un avantage aux jets de sauvegarde de Dextérité contre les effets que vous pouvez voir, comme les pièges ou les sorts. Pour bénéficier de cet effet vous ne devez pas être aveuglé, assourdi ou incapable d''agir.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-voie-du-berserker-frenesie', 'Frénésie', 'classe', 'Barbare', 'Voie du Berserker', 3, 'Dès que vous choisissez cette voie au niveau 3, vous pouvez choisir de sombrer dans un état de frénésie au cours de votre rage. Si vous le faites, pour la durée de votre rage, vous pouvez effectuer une unique attaque au corps à corps avec une arme en utilisant une action bonus à chacun de vos tours après celui-ci. Lorsque votre rage se termine, vous subissez un niveau d''épuisement.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-voie-primitive', 'Voie primitive', 'classe', 'Barbare', NULL, 3, 'Au niveau 3, vous choisissez la voie par laquelle s''exprime votre rage. Choisissez la voie du berserker ou la voie du guerrier totem. Votre choix vous accorde des capacités aux niveaux 3, 6, 10 et 14.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-amelioration-de-caracteristiques', 'Amélioration de caractéristiques', 'classe', 'Barbare', NULL, 4, 'Au niveau 4, puis par la suite aux niveaux 8, 12, 16 et 19, vous pouvez augmenter une valeur de caractéristique de votre choix de +2, ou bien augmenter deux valeurs de caractéristique de votre choix de +1. Vous ne pouvez cependant pas augmenter une caractéristique au-delà de 20 par ce biais.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-attaque-supplementaire', 'Attaque supplémentaire', 'classe', 'Barbare', NULL, 5, 'À partir du niveau 5, vous pouvez attaquer deux fois, au lieu d''une seule, chaque fois que vous réalisez l''action Attaquer durant votre tour.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-deplacement-rapide', 'Déplacement rapide', 'classe', 'Barbare', NULL, 5, 'Au niveau 5, votre vitesse augmente de 3 mètres tant que vous ne portez pas d''armure lourde.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-voie-du-berserker-rage-aveugle', 'Rage aveugle', 'classe', 'Barbare', 'Voie du Berserker', 6, 'À partir du niveau 6, vous ne pouvez pas être charmé ou effrayé tant que vous êtes en rage. Si vous êtes déjà charmé ou effrayé lorsque vous entrez en rage, l''effet est suspendu le temps de votre rage.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-instinct-sauvage', 'Instinct sauvage', 'classe', 'Barbare', NULL, 7, 'Au niveau 7, vos instincts sont si aiguisés que vous obtenez un avantage aux jets d''initiative. De plus, si vous êtes surpris au début du combat et que vous n''êtes pas incapable d''agir, vous pouvez jouer normalement durant votre premier tour, mais seulement si vous entrez en rage avant de faire quoique ce soit d''autre à ce tour.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-critique-brutal', 'Critique brutal', 'classe', 'Barbare', NULL, 9, 'À partir du niveau 9, vous pouvez lancer un dé de dégâts de votre arme en plus lorsque vous déterminez les dégâts supplémentaires que vous infligez sur un coup critique réussi avec une attaque au corps à corps. Ce bonus aux dégâts passe à deux dés au niveau 13 et à trois dés au niveau 17.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-voie-du-berserker-presence-intimidante', 'Présence intimidante', 'classe', 'Barbare', 'Voie du Berserker', 10, 'À partir du niveau 10, vous pouvez utiliser votre action pour effrayer quelqu''un avec votre présence effrayante. Pour ce faire, choisissez une créature que vous pouvez voir à 9 mètres maximum de vous. Si la créature peut vous voir ou vous entendre, elle doit réussir un jet de sauvegarde de Sagesse (DD égal à 8 + votre bonus de maîtrise + votre modificateur de Charisme) ou vous l''effrayez jusqu''à la fin de votre prochain tour. Aux tours suivants, vous pouvez utiliser votre action pour augmenter d''un tour supplémentaire la durée de cet effet sur la créature effrayée.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-rage-implacable', 'Rage implacable', 'classe', 'Barbare', NULL, 11, 'À partir du niveau 11, votre rage vous permet de continuer à combattre en dépit des graves blessures qui vous affectent. Si vous tombez à 0 point de vie pendant votre rage et que vous ne mourrez pas sur le coup, vous pouvez faire un jet de sauvegarde de Constitution DD 10.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-represailles', 'Représailles', 'classe', 'Barbare', NULL, 14, 'Lorsque vous subissez des dégâts d''une créature située à 1,50 mètre de vous, vous pouvez utiliser votre réaction pour effectuer une attaque au corps à corps avec une arme contre cette créature.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-rage-persistante', 'Rage persistante', 'classe', 'Barbare', NULL, 15, 'En atteignant le niveau 15, votre rage est si intense qu''elle ne s''arrête prématurément qu''à la condition que vous tombiez inconscient ou que vous choisissiez de l''arrêter.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-puissance-indomptable', 'Puissance indomptable', 'classe', 'Barbare', NULL, 18, 'Au niveau 18, si le résultat d''un de vos jets de Force est inférieur à votre valeur de Force, vous pouvez utiliser votre valeur de Force à la place de votre résultat.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barbare-champion-primitif', 'Champion primitif', 'classe', 'Barbare', NULL, 20, 'Au niveau 20, vous êtes l''incarnation de la puissance du monde sauvage. Vos valeurs de Force et de Constitution augmentent de 4. Votre maximum dans ces valeurs de caractéristique est maintenant de 24.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barde-incantation', 'Incantation', 'classe', 'Barde', NULL, 1, 'Le Charisme est votre caractéristique d''incantation pour vos sorts de barde.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barde-inspiration-bardique', 'Inspiration bardique', 'classe', 'Barde', NULL, 1, 'Inspiration bardique (d6) au niveau 1, augmente à d8 au niveau 5, d10 au niveau 10, et d12 au niveau 15.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barde-repos-revigorant', 'Repos revigorant', 'classe', 'Barde', NULL, 1, 'Vous pouvez utiliser de la musique ou une oraison apaisante lors d''un repos court pour aider à revitaliser vos alliés blessés. Si vous ou toutes créatures amies qui peuvent entendre votre représentation récupérez des points de vie à la fin du repos court en dépensant un ou plusieurs dés de vie, chacune de ces créatures récupère 1d6 points de vie supplémentaires. Les points de vie supplémentaires augmentent lorsque vous atteignez certains niveaux dans cette classe : 1d8 au niveau 9, 1d10 au niveau 13 et 1d12 au niveau 17.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barde-chant-reposant', 'Chant reposant', 'classe', 'Barde', NULL, 2, 'Chant reposant (d6) au niveau 2, augmente à d8 au niveau 9, et d12 au niveau 13.')
