insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barde-college-du-savoir-maitrises-supplementaires', 'Maîtrises supplémentaires', 'classe', 'Barde', 'Collège du Savoir', 3, 'Lorsque vous rejoignez le collège du savoir au niveau 3, vous gagnez la maîtrise de trois compétences de votre choix.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barde-college-du-savoir-mots-cinglants', 'Mots cinglants', 'classe', 'Barde', 'Collège du Savoir', 3, 'Également au niveau 3, vous apprenez à utiliser votre esprit pour détourner l''attention ou semer la confusion, ainsi qu''à saper la confiance et la compétence des autres. Quand une créature que vous pouvez voir dans un rayon de 18 mètres autour de vous fait un jet d''attaque, de caractéristique ou de dégâts, vous pouvez utiliser votre réaction pour dépenser une utilisation d''Inspiration bardique et soustraire votre jet du résultat de la cible. Vous pouvez choisir d''utiliser cette capacité après que la créature ait fait son jet, mais vous devez le faire avant que le MD ne dise si son jet est un succès ou un échec, ou avant que la créature inflige ses dégâts. La créature est immunisée si elle ne peut pas vous entendre ou si les charmes ne l''affectent pas.')
