insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barde-amelioration-de-caracteristiques', 'Amélioration de caractéristiques', 'classe', 'Barde', NULL, 4, 'Capacité obtenue aux niveaux 4, 8, 12, 16 et 19.')
