insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barde-college-du-savoir-secrets-magiques-supplementaires', 'Secrets magiques supplémentaires', 'classe', 'Barde', 'Collège du Savoir', 6, 'Au niveau 6, vous apprenez deux sorts de votre choix de n''importe quelle classe. Les sorts choisis doivent être d''un niveau que vous pouvez lancer, comme le montre la table du barde, ou être des sorts mineurs. Les sorts choisis comptent comme des sorts de barde pour vous, mais ne comptent pas pour le nombre de sorts.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barde-secrets-magiques-supplementaires', 'Secrets magiques supplémentaires', 'classe', 'Barde', NULL, 6, 'Vous apprenez deux sorts de votre choix de n''importe quelle classe. Les sorts choisis doivent être d''un niveau que vous pouvez lancer, comme le montre la table du barde, ou être des sorts mineurs. Les sorts choisis comptent comme des sorts de barde pour vous, mais ne comptent pas pour le nombre de sorts de barde connus.')
