insert into features (slug, nom, type, source, sous_source, niveau, description) values ('barde-competence-hors-pair', 'Compétence hors-pair', 'classe', 'Barde', NULL, 14, 'Quand vous faites un jet de caractéristique, vous pouvez utiliser une Inspiration bardique. Lancez le dé d''Inspiration bardique et ajoutez le résultat à votre jet de caractéristique. Vous pouvez choisir de le faire après avoir fait votre jet de votre caractéristique, mais vous devez le faire avant que le MD ne vous indique si vous réussissez ou échouez.')
