insert into features (slug, nom, type, source, sous_source, niveau, description) values ('chasseur-attaque-tourbillonnante', 'Attaque tourbillonnante', 'classe', 'Chasseur', NULL, 11, 'Vous pouvez utiliser votre action pour réaliser une attaque au corps à corps contre toutes les créatures à 1,50 mètre ou moins de vous, avec un jet d''attaque distinct pour chaque cible.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('chasseur-volee', 'Volée', 'classe', 'Chasseur', NULL, 11, 'Vous pouvez utiliser votre action pour faire une attaque à distance contre n''importe quel nombre de créatures situées à 3 mètres ou moins d''un point que vous pouvez voir et à portée de votre arme. Vous devez avoir assez de munitions pour chaque cible, logiquement, et devez faire un jet d''attaque distinct pour chaque cible.')
