insert into features (slug, nom, type, source, sous_source, niveau, description) values ('chasseur-esquive-instinctive', 'Esquive instinctive', 'classe', 'Chasseur', NULL, 15, 'Quand un attaquant que vous pouvez voir vous touche lors d''une attaque, vous pouvez utiliser votre réaction pour réduire de moitié les dégâts de l''attaque contre vous.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('chasseur-esquive-totale', 'Esquive totale', 'classe', 'Chasseur', NULL, 15, 'Vous pouvez vous retirer prestement de la trajectoire de certaines zones d''effet, comme celles du souffle ardent d''un dragon rouge ou d''un sort de foudre. Lorsque vous êtes soumis à un effet qui vous permet de faire un jet de sauvegarde de Dextérité pour ne prendre que la moitié des dégâts, vous ne prenez à la place aucun dégât si vous réussissez le jet, et seulement la moitié des dégâts si vous échouez.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('chasseur-retour-de-baton', 'Retour de bâton', 'classe', 'Chasseur', NULL, 15, 'Quand une créature hostile vous manque lors d''une attaque au corps à corps, vous pouvez utiliser votre réaction pour forcer cette créature à répéter la même attaque contre une autre créature (autre qu''elle-même) de votre choix.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-caracteristique-d-incantation', 'Caractéristique d''incantation', 'classe', 'Druide', NULL, NULL, 'La Sagesse est votre caractéristique d''incantation pour vos sorts de druide, étant donné que votre puissance magique dépend de votre dévotion ainsi que de votre connexion à la nature. Vous utilisez votre Sagesse chaque fois qu''un sort se réfère à votre capacité de lancer des sorts. En outre, vous utilisez votre modificateur de Sagesse pour définir le DD du jet de sauvegarde d''un sort de druide que vous lancez ainsi que pour le jet d''attaque de celui-ci.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-druidique', 'Druidique', 'classe', 'Druide', NULL, NULL, 'Vous connaissez le druidique, le langage secret des druides. Vous pouvez parler cette langue et l''utiliser pour laisser des messages secrets. Vous, et les autres personnes connaissant ce langage, remarquez automatiquement un tel message.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-focaliseur-d-incantation', 'Focaliseur d''incantation', 'classe', 'Druide', NULL, NULL, 'Vous pouvez utiliser un focaliseur druidique comme focaliseur d''incantation pour vos sorts de druide.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-metamorphose', 'Métamorphose', 'classe', 'Druide', NULL, NULL, 'Tant que vous êtes transformé, les règles suivantes s''appliquent : Vos statistiques de jeu sont remplacées par celles de la bête, mais vous conservez votre alignement, votre personnalité et vos valeurs de Charisme, Intelligence et Sagesse. Vous conservez également vos maîtrises de jets de sauvegarde et de compétences, en plus de gagner celles de la créature. Si la créature a les mêmes maîtrises que vous et que son bonus dans ce bloc de stat est supérieur au vôtre, utilisez son bonus. Si la créature possède des actions légendaires ou des actions de repaire, vous ne pouvez pas les utiliser. Quand vous vous transformez, vous endossez également les points de vie de la bête et ses dés de vie. Lorsque vous reprenez votre forme vous récupérez le nombre de points de vie que vous aviez avant votre transformation. De plus, si vous vous retransformez parce que vous êtes tombé à 0 point de vie, tous les dégâts supplémentaires sont encaissés par les points de vie de votre forme normale. Vous ne pouvez pas lancer de sorts, et votre capacité à parler ou effectuer toute action qui nécessite des mains est limitée aux possibilités qu''offre votre forme de bête. Toutefois, vous transformer ne brise pas votre concentration sur un sort que vous aviez déjà lancé, ni ne vous empêche d''utiliser une action pour rediriger un sort. Vous conservez les bénéfices de toutes vos capacités de classe, de race, ou de n''importe quelle autre origine, et vous pouvez les utiliser si vous en êtes physiquement capable. Cependant, vous ne pouvez pas utiliser de sens spéciaux, comme la vision dans le noir, sauf si votre nouvelle forme les possède également. Vous choisissez si votre équipement tombe sur le sol, fusionne avec votre nouvelle forme ou est porté par votre nouvelle forme.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-rituel', 'Rituel', 'classe', 'Druide', NULL, NULL, 'Vous pouvez lancer un sort de druide en tant que rituel si ce sort possède l''étiquette rituel et si vous avez préparé le sort.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-sorts-prepares', 'Sorts préparés', 'classe', 'Druide', NULL, NULL, 'Avec une Sagesse de 16, votre liste de sorts préparés peut inclure six sorts de niveau 1 et 2, selon n''importe quelle combinaison. Vous pouvez modifier votre liste de sorts préparés lorsque vous terminez un repos long. Préparer une nouvelle liste de sorts de druide nécessite du temps pour prier et méditer : au moins 1 minute par niveau de sort pour chaque sort sur votre liste.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-incantation', 'Incantation', 'classe', 'Druide', NULL, 1, 'Puisant dans l''essence divine de la nature elle-même, vous pouvez lancer des sorts pour modeler cette essence selon votre volonté.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-cercle-druidique', 'Cercle Druidique', 'classe', 'Druide', NULL, 2, 'Au niveau 2, vous devez choisir à quel cercle de druide vous appartenez : le cercle de la terre ou le cercle de la lune. Votre choix vous confère de nouvelles capacités aux niveaux 2, puis 6, 10, et 14.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-forme-sauvage', 'Forme sauvage', 'classe', 'Druide', NULL, 2, 'À partir du niveau 2, vous pouvez utiliser votre action pour prendre par magie la forme d''une bête que vous avez déjà vue auparavant. Vous pouvez utiliser ce pouvoir deux fois. Vous récupérez les utilisations dépensées après avoir effectué un repos court ou long. Vous pouvez rester sous forme de bête un nombre d''heures égal à la moitié de votre niveau de druide (arrondi à l''entier inférieur). Une fois le temps écoulé, vous reprenez votre forme normale à moins que vous ne dépensiez une nouvelle utilisation de cette capacité. Vous pouvez également revenir plus tôt à votre forme normale en utilisant une action bonus lors de votre tour. Vous revenez automatiquement à votre forme normale si vous tombez inconscient, si vous tombez à 0 point de vie ou si vous mourrez.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-cercle-de-la-terre-recuperation-naturelle', 'Récupération naturelle', 'classe', 'Druide', 'Cercle de la Terre', 2, 'Vous pouvez récupérer une partie de votre énergie magique en méditant et communiant avec la nature. Lors d''un repos court, vous choisissez les emplacements de sorts que vous souhaitez récupérer. Les emplacements de sorts doivent avoir un niveau cumulé inférieur ou égal à la moitié de votre niveau de druide (arrondi à l''entier supérieur), et aucun de ces emplacements ne doit être de niveau 6 ou supérieur. Vous ne pouvez pas utiliser de nouveau cette capacité avant d''avoir terminé un repos long.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-cercle-de-la-terre-sort-mineur-supplementaire', 'Sort mineur supplémentaire', 'classe', 'Druide', 'Cercle de la Terre', 2, 'Vous apprenez un sort mineur de druide supplémentaire de votre choix. Ce sort mineur ne compte pas dans le nombre de sorts mineurs de druide que vous connaissez.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-cercle-de-la-terre-sorts-de-cercle', 'Sorts de cercle', 'classe', 'Druide', 'Cercle de la Terre', 3, 'Votre connexion mystique à la terre vous permet de lancer certains sorts. Aux niveaux 3, 5, 7 et 9, vous accédez à des sorts de cercle liés à la terre qui vous a vu devenir druide. Choisissez ce terrain (arctique, désert, forêt, littoral, marais, montagne, Outreterre ou plaine) et consultez la liste de sorts associée. Une fois que vous avez accès à un sort de cercle, ce sort est constamment préparé et ne compte pas dans le total de sorts que vous pouvez préparer chaque jour. Si vous accédez à un sort qui n''apparaît pas dans la liste de sorts du druide, ce sort est néanmoins considéré comme étant un sort de druide pour vous.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-amelioration-de-caracteristiques', 'Amélioration de Caractéristiques', 'classe', 'Druide', NULL, 4, 'Au niveau 4, puis par la suite aux niveaux 8, 12, 16 et 19, vous pouvez augmenter une valeur de caractéristique de votre choix de +2, ou bien augmenter deux valeurs de caractéristique de votre choix de +1 chacune.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-foulee-tellurique', 'Foulée tellurique', 'classe', 'Druide', NULL, 6, 'À partir du niveau 6, vous déplacer sur un terrain difficile non magique ne vous coûte pas de déplacement supplémentaire. Vous pouvez également traverser la végétation non magique sans être ralenti et sans subir de dégâts si elle est constituée d''épines, de pointes ou d''autres inconvénients similaires. De plus, vous avez un avantage aux jets de sauvegarde contre les plantes qui ont été créées magiquement ou manipulées pour empêcher les mouvements, comme celles créées par le sort enchevêtrement.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-protege-de-dame-nature', 'Protégé de Dame Nature', 'classe', 'Druide', NULL, 10, 'Lorsque vous atteignez le niveau 10, vous ne pouvez plus être charmé ou effrayé par les élémentaires ou les fées, et vous êtes immunisé contre les poisons et les maladies.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-sanctuaire-de-dame-nature', 'Sanctuaire de Dame Nature', 'classe', 'Druide', NULL, 14, 'Lorsque vous atteignez le niveau 14, les créatures du monde naturel ressentent votre connexion avec la nature et hésitent à vous attaquer. Quand une bête ou une plante vous attaque, cette créature doit réussir un jet de sauvegarde de Sagesse contre votre DD de sort de druide. Si elle échoue, la créature doit choisir une autre cible, ou bien l''attaque rate automatiquement. En cas de jet de sauvegarde réussi, la créature est immunisée à cet effet pour 24 heures. La créature est consciente de cet effet avant qu''elle n''effectue son attaque contre vous.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-incantation-animale', 'Incantation animale', 'classe', 'Druide', NULL, 18, 'Vous pouvez lancer sous votre Forme sauvage la plupart de vos sorts de druide. Vous pouvez réaliser les composantes somatiques et verbales d''un sort de druide lorsque vous êtes sous forme de bête, mais vous ne pouvez pas utiliser de composante matérielle.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-jeunesse-eternelle', 'Jeunesse éternelle', 'classe', 'Druide', NULL, 18, 'La magie primordiale qui vous parcourt ralentit le vieillissement de votre corps. Vous ne prenez qu''un an d''âge toutes les dix années écoulées.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('druide-archidruide', 'Archidruide', 'classe', 'Druide', NULL, 20, 'Vous pouvez utiliser Forme sauvage un nombre illimité de fois par jour. De plus, vous pouvez ignorer les composantes verbales et somatiques de vos sorts de même que toute composante matérielle non coûteuse qui n''est consommée par le sort. Vous gagnez ces avantages que vous soyez sous votre forme normale ou sous votre forme de bête de Forme sauvage.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-caracteristique-d-incantation', 'Caractéristique d''incantation', 'classe', 'Ensorceleur', NULL, NULL, 'Le Charisme est votre caractéristique d''incantation pour vos sorts d''ensorceleur, car la puissance de votre magie repose sur votre capacité à projeter votre volonté dans le monde. Vous utilisez votre Charisme chaque fois qu''un sort fait référence à votre capacité de lancer des sorts. En outre, vous utilisez votre modificateur de Charisme pour définir le DD du jet de sauvegarde d''un sort d''ensorceleur que vous lancez et quand vous effectuez un jet d''attaque.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-focaliseur-d-incantation', 'Focaliseur d''incantation', 'classe', 'Ensorceleur', NULL, NULL, 'Vous pouvez utiliser un focaliseur arcanique comme focaliseur d''incantation pour vos sorts d''ensorceleur.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-sort-puissant', 'Sort puissant', 'classe', 'Ensorceleur', NULL, NULL, 'Lorsque vous lancez un sort, vous pouvez dépenser 1 point de sorcellerie pour relancer un nombre de dés de dégâts ne dépassant pas votre modificateur de Charisme (minimum 1). Vous devez forcément utiliser les nouveaux dégâts. Vous pouvez utiliser Sort puissant même si vous avez déjà utilisé une option différente de métamagie lors du lancer de ce sort.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-lignee-draconique-ancetre-draconique', 'Ancêtre draconique', 'classe', 'Ensorceleur', 'Lignée draconique', 1, 'Au niveau 1, vous choisissez un type de dragon comme votre ancêtre. Le type de dégât associé à chaque dragon est utilisé par les capacités que vous gagnerez plus tard. Vous pouvez parler, lire et écrire le draconique. De plus, chaque fois que vous faites un jet de Charisme pour interagir avec des dragons, votre bonus de maîtrise est doublé s''il s''applique au jet.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-incantation', 'Incantation', 'classe', 'Ensorceleur', NULL, 1, 'Un événement dans votre passé, ou dans la vie d''un parent ou un ancêtre, vous a laissé une marque indélébile, en vous insufflant la magie des arcanes. Cette source de magie, quelle que soit son origine, alimente vos sorts.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-origine-magique', 'Origine magique', 'classe', 'Ensorceleur', NULL, 1, 'Capacité de l''Ensorceleur obtenue au niveau 1.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-lignee-draconique-resistance-draconique', 'Résistance draconique', 'classe', 'Ensorceleur', 'Lignée draconique', 1, 'La magie qui coule à travers votre corps fait émerger des traits physiques de vos ancêtres dragons. Au niveau 1, votre maximum de points de vie augmente de 1 et également de 1 à chaque fois que vous gagnez un niveau dans cette classe. En outre, des parties de votre peau sont couvertes d''un mince reflet d''écailles de dragon. Lorsque vous ne portez pas d''armure, votre CA est égale à 13 + votre modificateur de Dextérité.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-flexibilite-des-sorts', 'Flexibilité des sorts', 'classe', 'Ensorceleur', NULL, 2, 'Vous pouvez utiliser vos points de sorcellerie pour gagner des emplacements de sorts supplémentaires ou sacrifier des emplacements de sorts pour gagner des points de sorcellerie supplémentaires. Vous apprenez d''autres façons d''utiliser vos points de sorcellerie lorsque vous atteignez des niveaux plus élevés. Tout emplacement de sort créé de cette manière disparaît lorsque vous terminez un repos long.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-points-de-sorcellerie', 'Points de sorcellerie', 'classe', 'Ensorceleur', NULL, 2, 'Vous avez 2 points de sorcellerie, et vous en gagnez plus à des niveaux supérieurs, comme indiqué dans la colonne de Points de sorcellerie de la table. Vous ne pouvez jamais avoir plus de points de sorcellerie que ce que vous permet votre niveau dans la table. Vous récupérez tous les points de sorcellerie utilisés lorsque vous terminez un repos long.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-source-de-magie', 'Source de magie', 'classe', 'Ensorceleur', NULL, 2, 'Capacité de l''Ensorceleur obtenue au niveau 2.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-metamagie', 'Métamagie', 'classe', 'Ensorceleur', NULL, 3, 'Capacité de l''Ensorceleur obtenue au niveau 3.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-sort-accelere', 'Sort accéléré', 'classe', 'Ensorceleur', NULL, 3, 'Lorsque vous lancez un sort qui a un temps d''incantation de 1 action, vous pouvez dépenser 2 points de sorcellerie pour changer le temps d''incantation à 1 action bonus pour lancer ce sort.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-sort-ample', 'Sort ample', 'classe', 'Ensorceleur', NULL, 3, 'Quand vous lancez un sort qui a une portée de 1,50 mètre ou plus, vous pouvez dépenser 1 point de sorcellerie pour doubler la portée du sort. Si le sort a une portée de contact, vous pouvez dépenser 1 point de sorcellerie pour faire passer sa portée à 9 mètres.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-sort-etendu', 'Sort étendu', 'classe', 'Ensorceleur', NULL, 3, 'Lorsque vous lancez un sort qui a une durée de 1 minute ou plus, vous pouvez dépenser 1 point de sorcellerie pour doubler sa durée (maximum 24 heures).')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-sort-intensifie', 'Sort intensifié', 'classe', 'Ensorceleur', NULL, 3, 'Lorsque vous lancez un sort qui oblige une créature à faire un jet de sauvegarde pour résister à ses effets, vous pouvez dépenser 3 points de sorcellerie pour donner à une cible du sort un désavantage à son premier jet de sauvegarde contre le sort.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-sort-jumeau', 'Sort jumeau', 'classe', 'Ensorceleur', NULL, 3, 'Quand vous lancez un sort qui a pour cible une seule créature et qui n''a pas une portée personnelle, vous pouvez dépenser un nombre de points de sorcellerie égal au niveau du sort pour viser une deuxième créature à portée avec le même sort (1 point de sorcellerie si le sort est un sort mineur). Pour pouvoir utiliser cette option de métamagie, le sort doit être incapable de cibler plus d''une créature au niveau auquel il est lancé.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-sort-prevenant', 'Sort prévenant', 'classe', 'Ensorceleur', NULL, 3, 'Lorsque vous lancez un sort qui force les autres créatures à faire un jet de sauvegarde, vous pouvez libérer de cette obligation du sort certaines de ces créatures. Pour ce faire, dépensez 1 point de sorcellerie et choisissez un nombre de créatures égal à votre modificateur de Charisme (minimum 1 créature). Chaque créature choisie réussie automatiquement son jet de sauvegarde contre le sort.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-sort-renforce', 'Sort renforcé', 'classe', 'Ensorceleur', NULL, 3, 'Lorsque vous lancez les dégâts pour un sort, vous pouvez dépenser 1 point de sorcellerie pour relancer un nombre de dés de dégâts ne dépassant pas votre modificateur de Charisme (minimum 1). Vous devez forcément utiliser les nouveaux dégâts. Vous pouvez utiliser Sort puissant même si vous avez déjà utilisé une option différente de métamagie lors du lancer de ce sort.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-sort-subtil', 'Sort subtil', 'classe', 'Ensorceleur', NULL, 3, 'Lorsque vous lancez un sort, vous pouvez dépenser 1 point de sorcellerie pour le lancer sans composantes somatiques ou verbales.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-amelioration-de-caracteristiques', 'Amélioration de caractéristiques', 'classe', 'Ensorceleur', NULL, 4, 'Au niveau 4, puis par la suite aux niveaux 8, 12, 16 et 19, vous pouvez augmenter une valeur de caractéristique de votre choix de +2, ou bien augmenter deux valeurs de caractéristique de votre choix de +1. Vous ne pouvez cependant pas augmenter une caractéristique au-delà de 20 par ce biais.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-lignee-draconique-affinite-elementaire', 'Affinité élémentaire', 'classe', 'Ensorceleur', 'Lignée draconique', 6, 'À partir du niveau 6, lorsque vous lancez un sort qui inflige des dégâts du type associé à votre ascendance draconique, vous pouvez ajouter votre modificateur de Charisme aux dégâts d''un seul jet. Dans le même temps, vous pouvez dépenser 1 point de sorcellerie pour gagner une résistance à ce type de dégâts pendant 1 heure.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-ascendance-draconique-affinite-elementaire', 'Affinité Élémentaire', 'classe', 'Ensorceleur', 'Ascendance Draconique', 6, 'À partir du niveau 6, lorsque vous lancez un sort qui inflige des dégâts du type associé à votre ascendance draconique, vous pouvez ajouter votre modificateur de Charisme aux dégâts d''un seul jet. Dans le même temps, vous pouvez dépenser 1 point de sorcellerie pour gagner une résistance à ce type de dégâts pendant 1 heure.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-lignee-draconique-ailes-draconiques', 'Ailes draconiques', 'classe', 'Ensorceleur', 'Lignée draconique', 14, 'Au niveau 14, vous obtenez des ailes draconiques.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-ascendance-draconique-ailes-draconiques', 'Ailes Draconiques', 'classe', 'Ensorceleur', 'Ascendance Draconique', 14, 'Au niveau 14, vous obtenez la possibilité de faire pousser une paire d''ailes de dragon dans votre dos et gagnez une vitesse de vol égale à votre vitesse actuelle. Vous pouvez créer ces ailes en une action bonus à votre tour. Elles durent jusqu''à ce que vous les rejetiez par une action bonus à votre tour. Vous ne pouvez pas faire apparaître vos ailes si vous portez une armure, sauf si l''armure est faite pour les accueillir. De même, des vêtements non prévus pour accueillir vos ailes pourraient être détruits lorsque vous les faîtes apparaître.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-ascendance-draconique-presence-draconique', 'Présence Draconique', 'classe', 'Ensorceleur', 'Ascendance Draconique', 18, 'À partir du niveau 18, vous pouvez canaliser la présence effrayante de votre ancêtre dragon, causant autour de vous la terreur ou la fascination. En une action, vous pouvez dépenser 5 points de sorcellerie pour déclencher ce pouvoir et dégager une aura de fascination ou de peur (à votre choix) sur une distance de 18 mètres. Pendant 1 minute ou jusqu''à ce que vous perdiez votre concentration (comme lorsqu''on lance un sort avec concentration), chaque créature hostile qui commence son tour dans cette aura doit réussir un jet de sauvegarde de Sagesse ou être charmée (si vous avez choisi la fascination) ou effrayée (si vous avez choisi la peur) jusqu''à ce que l''aura se termine. Une créature qui réussit sur ce jet de sauvegarde est immunisée de votre aura pendant 24 heures.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('ensorceleur-restauration-ensorcelee', 'Restauration ensorcelée', 'classe', 'Ensorceleur', NULL, 20, 'Au niveau 20, vous regagnez 4 points de sorcellerie dépensés chaque fois que vous terminez un repos court.')
