insert into features (slug, nom, type, source, sous_source, niveau, description) values ('moine-deluge-de-coups', 'Déluge de coups', 'classe', 'Moine', NULL, NULL, 'Immédiatement après avoir utilisé une action Attaquer au cours de votre tour, vous pouvez dépenser 1 point ki pour effectuer deux attaques à mains nues via une action bonus.')
