insert into features (slug, nom, type, source, sous_source, niveau, description) values ('moine-deplacement-aerien', 'Déplacement aérien', 'classe', 'Moine', NULL, NULL, 'Vous pouvez dépenser 1 point ki pour utiliser l''action Se Désengager ou l''action Foncer via une action bonus au cours de votre tour, de plus votre distance de saut est doublée pour le tour.')
