insert into features (slug, nom, type, source, sous_source, niveau, description) values ('moine-arts-martiaux', 'Arts martiaux', 'classe', 'Moine', NULL, 1, 'Au niveau 1, votre pratique des arts martiaux vous donne la maîtrise des styles de combat utilisant les attaques à mains nues et les armes de moine, qui sont l''épée courte et toutes les armes de corps à corps courantes qui n''ont ni la propriété à deux mains, ni la propriété lourde. Vous gagnez les avantages suivants lorsque vous êtes à mains nues ou ne maniez que des armes de moine et que vous n''êtes équipé ni d''armure ni de bouclier : Vous pouvez utiliser la Dextérité à la place de la Force aux jets d''attaque et de dégâts de vos attaques à mains nues et avec des armes de moine. Vous pouvez lancer un d4 à la place des dégâts normaux de votre attaque à mains nues ou de vos armes de moine. Ce dé change lorsque vous gagnez des niveaux de moine.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('moine-defense-sans-armure', 'Défense sans armure', 'classe', 'Moine', NULL, 1, 'Dès le niveau 1, tant que vous n''êtes équipé ni d''une armure, ni d''un bouclier, votre CA est égale à 10 + votre modificateur de Dextérité + votre modificateur de Sagesse.')
