insert into features (slug, nom, type, source, sous_source, niveau, description) values ('moine-voie-de-la-paume-technique-de-la-paume', 'Technique de la paume', 'classe', 'Moine', 'Voie de la Paume', 3, 'Vous pouvez manipuler le ki de votre ennemi tout en utilisant le vôtre. À chaque fois que vous touchez une créature avec l''une des attaques offertes par Déluge de coups, vous pouvez affliger votre cible de l''un des effets suivants : Elle doit réussir un jet de sauvegarde de Dextérité sous peine de tomber à terre. Elle doit réussir un jet de sauvegarde de Force. En cas d''échec, vous pouvez la repousser de 4,50 mètres. Elle ne peut utiliser de réaction jusqu''à la fin de votre prochain tour.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
