insert into features (slug, nom, type, source, sous_source, niveau, description) values ('moine-voie-de-la-paume-plenitude-physique', 'Plénitude physique', 'classe', 'Moine', 'Voie de la Paume', 6, 'Vous gagnez la capacité de vous soigner vous-même. Par une action, vous pouvez récupérer un nombre de points de vie égal à trois fois votre niveau de moine. Vous devez terminer un repos long avant de pouvoir utiliser de nouveau cette capacité.')
