insert into features (slug, nom, type, source, sous_source, niveau, description) values ('moine-voie-de-la-paume-tranquillite', 'Tranquillité', 'classe', 'Moine', 'Voie de la Paume', 11, 'Vous pouvez entrer dans une méditation spéciale qui vous enveloppe dans une aura de paix. À la fin d''un repos long, vous gagnez l''effet du sort sanctuaire jusqu''au début de votre prochain repos long (le sort peut se terminer prématurément comme n''importe quel sort de sanctuaire). Le DD de sauvegarde pour ce sort est égal à 8 + votre modificateur de Sagesse + votre bonus de maîtrise.')
