on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('moine-jeunesse-eternelle', 'Jeunesse éternelle', 'classe', 'Moine', NULL, 15, 'Jeunesse éternelle')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('moine-voie-de-la-paume-paume-fremissante', 'Paume frémissante', 'classe', 'Moine', 'Voie de la Paume', 17, 'Vous gagnez la capacité de transmettre des vibrations létales au corps de quelqu''un. Lorsque vous touchez une créature avec une attaque à mains nues, vous pouvez dépenser 3 points ki pour déclencher ces vibrations imperceptibles, qui restent en place un nombre de jour égal à votre niveau de moine. Les vibrations sont inoffensives tant que vous n''utilisez pas d''action pour les arrêter. Pour ce faire, vous et votre cible devez vous trouver dans le même plan d''existence. Lorsque vous utilisez cette action, la créature doit effectuer un jet de sauvegarde de Constitution. Si elle l''échoue, elle tombe à 0 point de vie. Si elle réussit, elle subit 10d10 dégâts nécrotiques. Vous ne pouvez affliger de cet effet qu''une seule créature à la fois. Vous pouvez choisir de mettre fin aux vibrations de manière inoffensive pour la cible, et ce sans dépenser d''action.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('moine-corps-vide', 'Corps vide', 'classe', 'Moine', NULL, 18, 'Corps vide')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('moine-desertion-de-l-ame', 'Désertion de l''Âme', 'classe', 'Moine', NULL, 18, 'À partir du niveau 18, vous pouvez utiliser votre action pour dépenser 4 points ki et ainsi devenir invisible pendant 1 minute. Au cours de cette période, vous obtenez également la résistance à tous les dégâts, à l''exception des dégâts de force. De plus, vous pouvez dépenser 8 points de ki pour lancer le sort projection astral, sans avoir besoin des composantes matérielles. De cette manière, vous ne pouvez pas prendre d''autres créatures avec vous.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('moine-perfection-de-l-etre', 'Perfection de l''être', 'classe', 'Moine', NULL, 20, 'Perfection de l''être')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-pacte-du-familier-appel-de-familier', 'Appel de familier', 'classe', 'Occultiste', 'Pacte du Familier', NULL, 'Vous pouvez lancer le sort appel de familier et pouvez le lancer sous forme de rituel. Ce sort n''est pas comptabilisé comme un sort connu. Lorsque vous lancez le sort, vous pouvez choisir une forme normale pour votre familier ou bien une des formes spéciales suivantes : esprit follet, diablotin, pseudodragon ou quasit. En outre, quand vous choisissez l''action Attaquer, vous pouvez renoncer à une de vos attaques pour permettre à votre familier d''attaquer. Lorsque vous laissez votre familier attaquer, il le fait avec sa réaction.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-armure-d-ombres', 'Armure d''Ombres', 'classe', 'Occultiste', NULL, NULL, 'Vous pouvez lancer armure de mage sur vous-même à volonté, sans dépenser d''emplacement de sort ni de composantes.')
