insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-langage-animal', 'Langage Animal', 'classe', 'Occultiste', NULL, NULL, 'Vous pouvez lancer communication avec les animaux à volonté, sans dépenser d''emplacement de sort.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-pacte-du-grimoire-livre-des-secrets-anciens', 'Livre des Secrets Anciens', 'classe', 'Occultiste', 'Pacte du Grimoire', NULL, 'Vous pouvez maintenant inscrire des rituels dans votre Livre des Ombres. Choisissez deux sorts de niveau 1 qui sont marqués comme rituel dans la liste de sorts de n''importe quelle classe. Les sorts apparaissent dans le livre et ne comptent pas dans le nombre de sorts connus. Si vous tenez votre Livre des Ombres en main, vous pouvez lancer ces sorts comme des rituels. Vous pouvez lancer ces sorts uniquement comme rituels, à moins que vous ne les appreniez par d''autres moyens. Vous pouvez aussi lancer un sort connu d''occultiste comme rituel s''il est marqué de cette manière. Durant vos aventures vous pouvez copier d''autres rituels dans votre Livre des Ombres. Lorsque vous trouvez ce genre de sorts, vous pouvez les ajouter dans votre livre du moment qu''ils sont d''un niveau égal ou inférieur à la moitié de votre niveau d''occultiste (arrondi au supérieur) et si vous avez le temps de faire la transcription. Pour chaque niveau de sort, celle-ci prend 2 heures et coûte 50 po d''encres rares nécessaires à sa transposition.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-mille-visages', 'Mille Visages', 'classe', 'Occultiste', NULL, NULL, 'Vous pouvez lancer déguisement à volonté, sans dépenser d''emplacement de sort.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-pacte-de-la-lame', 'Pacte de la Lame', 'classe', 'Occultiste', NULL, NULL, 'Vous pouvez utiliser une action pour créer une arme de pacte dans votre main libre. Vous pouvez choisir la forme que prend cette arme de corps à corps à chaque fois que vous la créez. Vous maîtrisez cette arme tant que vous la tenez en main. Cette arme est considérée comme magique au regard des résistances et des immunités aux attaques et aux dégâts non magiques. Votre arme de pacte disparaît si elle se trouve à plus de 1,50 mètre de vous pendant une minute ou plus. Elle disparaît également si vous utilisez à nouveau cette aptitude, si vous congédiez l''arme ou si vous mourrez. Vous pouvez transformer une arme magique pour en faire votre arme de pacte en effectuant un rituel spécial si vous tenez l''arme en main. Vous réalisez le rituel en 1 heure, ce qui peut être fait durant un repos court.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-pacte-du-grimoire', 'Pacte du Grimoire', 'classe', 'Occultiste', NULL, NULL, 'Votre patron vous offre un grimoire appelé un Livre des Ombres. Dès lors que vous bénéficiez de cette capacité, choisissez trois sorts mineurs dans la liste de sorts de n''importe quelle classe. Tant que vous portez le grimoire sur vous, vous pouvez lancer ces sorts mineurs à volonté. Ils ne comptent pas dans votre nombre de sorts mineurs connus. Même s''ils ne sont pas sur la liste de sorts d''occultiste, vous pouvez les considérer comme des sorts d''occultiste. Si vous perdez votre Livre des Ombres, vous pouvez réaliser une cérémonie de 1 heure pour en recevoir un nouveau de la part de votre patron. Cette cérémonie détruit le grimoire précédent et peut être réalisée durant un repos court ou long. Le grimoire se transforme en cendre quand vous mourrez.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-le-fielon-benediction-du-tenebreux', 'Bénédiction du ténébreux', 'classe', 'Occultiste', 'Le Fiélon', 1, 'À partir du niveau 1, lorsque vous réduisez une créature')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-le-tenebreux-benediction-du-tenebreux', 'Bénédiction du Ténébreux', 'classe', 'Occultiste', 'Le Ténébreux', 1, 'À partir du niveau 1, lorsque vous réduisez une créature hostile à 0 point de vie, vous gagnez un nombre de points de vie temporaires égal à votre modificateur de Charisme + votre niveau d''occultiste (minimum 1).')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-magie-de-pacte', 'Magie de pacte', 'classe', 'Occultiste', NULL, 1, 'Vos recherches arcaniques et la magie qui vous est conférée par votre patron vous ont donné des facilités avec les sorts.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-patron-d-outremonde', 'Patron d''Outremonde', 'classe', 'Occultiste', NULL, 1, 'Au niveau 1, vous avez conclu un marché avec un être d''Outremonde de votre choix : l''Archifée, le Fiélon ou le Grand Ancien. Celui-ci vous accorde des faveurs au niveau 1 puis aux niveaux 6, 10 et 14.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-manifestations-occultes', 'Manifestations occultes', 'classe', 'Occultiste', NULL, 2, 'Manifestations occultes')
