insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-faveur-de-pacte', 'Faveur de pacte', 'classe', 'Occultiste', NULL, 3, 'Faveur de pacte')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-pacte-de-la-chaine', 'Pacte de la Chaîne', 'classe', 'Occultiste', NULL, 3, 'Vous apprenez le sort appel de familier et pouvez le lancer sous forme de rituel. Ce sort n''est pas comptabilisé comme un sort connu. Lorsque vous lancez le sort, vous pouvez choisir une forme normale pour votre familier (voir le sort) ou bien une des formes spéciales suivantes : esprit follet, diablotin, pseudodragon ou quasit. En outre, quand vous choisissez l''action Attaquer, vous pouvez renoncer à une de vos attaques pour permettre à votre familier d''effectuer une action.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-amelioration-de-caracteristiques', 'Amélioration de caractéristiques', 'classe', 'Occultiste', NULL, 4, 'Vous pouvez augmenter une caractéristique de votre choix de 2 points ou deux caractéristiques de 1 point chacune.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-pacte-de-la-lame-lame-assoiffee', 'Lame Assoiffée', 'classe', 'Occultiste', 'Pacte de la Lame', 5, 'Vous pouvez attaquer deux fois avec votre arme de pacte, au lieu d''une seule, chaque fois que vous choisissez l''action Attaquer durant votre tour.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-lenteur-de-l-esprit', 'Lenteur de l''Esprit', 'classe', 'Occultiste', NULL, 5, 'Vous pouvez lancer lenteur une fois en utilisant un emplacement de sort d''occultiste. Vous ne pouvez le lancer de nouveau avant d''avoir terminé un repos long.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-maitre-des-ombres', 'Maître des Ombres', 'classe', 'Occultiste', NULL, 5, 'Lorsque vous êtes dans une zone de lumière faible ou de ténèbres, vous pouvez utiliser une action pour devenir invisible jusqu''à ce que vous bougiez ou que vous utilisiez une action ou une réaction.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-patron-d-outremonde-capacite-de-patron-d-outremonde', 'Capacité de patron d''Outremonde', 'classe', 'Occultiste', 'Patron d''Outremonde', 6, 'Au niveau 6, votre patron d''Outremonde vous confère une nouvelle capacité.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-le-tenebreux-chance-du-tenebreux', 'Chance du Ténébreux', 'classe', 'Occultiste', 'Le Ténébreux', 6, 'À partir du niveau 6, vous pouvez appeler votre patron afin qu''il modifie le sort en votre faveur. Lorsque vous effectuez un jet de caractéristique ou un jet de sauvegarde, vous pouvez utiliser cette capacité pour ajouter un d10 à votre jet. Vous pouvez décider de le faire après avoir lancé le dé initial, mais la décision doit être prise avant que l''effet ne se produise. Une fois que vous avez utilisé cette capacité, vous devez terminer un repos court ou long avant de pouvoir l''utiliser à nouveau.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-mot-d-effroi', 'Mot d''Effroi', 'classe', 'Occultiste', NULL, 7, 'Vous pouvez lancer confusion une fois en utilisant un emplacement de sort d''occultiste.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-le-tenebreux-resistance-fielonne', 'Résistance Fiélonne', 'classe', 'Occultiste', 'Le Ténébreux', 10, 'À partir du niveau 10, vous pouvez choisir un type de dégâts lorsque vous terminez un repos court ou long. Vous gagnez alors la résistance à ce type de dégâts jusqu''à ce que vous en choisissiez un autre grâce à cette capacité. Les dégâts causés par des armes magiques ou des armes en argent ignorent cette résistance.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-arcanum-mystique', 'Arcanum mystique', 'classe', 'Occultiste', NULL, 11, 'Au niveau 11, vous apprenez un arcanum mystique de niveau 6. À des niveaux supérieurs, vous apprenez des arcanums mystiques de niveau 7, 8 et 9.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-buveuse-de-vie', 'Buveuse de Vie', 'classe', 'Occultiste', NULL, 12, 'Quand vous touchez une créature avec votre arme de pacte, elle subit des dégâts nécrotiques supplémentaires égaux à votre modificateur de Charisme (minimum 1).')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-le-tenebreux-traversee-des-enfers', 'Traversée des Enfers', 'classe', 'Occultiste', 'Le Ténébreux', 14, 'À partir du niveau 14, lorsque vous touchez une créature avec une attaque, vous pouvez utiliser cette capacité pour transporter instantanément la cible vers les plans inférieurs. La créature disparaît et passe par un paysage de cauchemar. À la fin de votre prochain tour, la cible revient dans l''espace qu''elle occupait précédemment, ou dans l''espace libre le plus proche. Si la cible n''est pas un fiélon, elle prend 10d10 dégâts psychiques lorsqu''elle revient de son horrible expérience. Une fois que vous avez utilisé cette capacité, vous devez terminer un repos long avant de pouvoir l''utiliser à nouveau.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-chaines-des-carceres', 'Chaînes des Carcères', 'classe', 'Occultiste', NULL, 15, 'Vous pouvez lancer immobilisation de monstre à volonté (en ciblant un céleste, un démon ou un élémentaire) sans dépenser d''emplacement de sort ni de composantes.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-pacte-de-la-chaine-chaines-des-carceres', 'Chaînes des Carcères', 'classe', 'Occultiste', 'Pacte de la Chaîne', 15, 'Vous pouvez lancer immobilisation de monstre à volonté (en ciblant un céleste, un démon ou un élémentaire) sans dépenser d''emplacement de sort ni de composantes. Vous devez avoir terminé un repos long avant de pouvoir réutiliser cette manifestation sur la même créature.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-maitre-des-formes', 'Maître des Formes', 'classe', 'Occultiste', NULL, 15, 'Vous pouvez lancer modification d''apparence à volonté, sans dépenser d''emplacement de sort.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('occultiste-maitre-de-l-occulte', 'Maître de l''occulte', 'classe', 'Occultiste', NULL, 20, 'Au niveau 20, vous maîtrisez complètement votre magie occulte et vos pouvoirs d''occultiste atteignent leur apogée.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-renvoi-des-impies', 'Renvoi des impies', 'classe', 'Paladin', NULL, NULL, 'Au prix d''une action, vous présentez votre symbole sacré en psalmodiant une prière contre les morts-vivants ou les fiélons, utilisant votre Conduit divin. Chaque mort-vivant ou fiélon à 9 mètres autour de vous qui peuvent vous entendre ou vous voir, doivent faire un jet de sauvegarde de Sagesse. Si la créature rate son jet de sauvegarde, elle est renvoyée pendant 1 minute ou jusqu''à ce qu''elle prenne des dégâts. Une créature renvoyée doit passer ses actions à essayer de s''éloigner le plus loin possible de vous et ne peut volontairement se rapprocher à 9 mètres ou moins de vous. Elle ne peut pas avoir de réactions et peut utiliser ses actions seulement pour Foncer ou essayer de s''échapper d''un effet immobilisant. S''il n''y a nulle part où aller, la créature peut utiliser l''action Esquiver.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-imposition-des-mains', 'Imposition des mains', 'classe', 'Paladin', NULL, 1, 'Votre toucher béni peut guérir les blessures. Vous possédez une réserve de points de vie à soigner qui se récupère après chaque repos long. Avec cette réserve, vous pouvez restaurer un nombre total de points de vie égal à votre niveau de paladin multiplié par 5. Au prix d''une action, vous pouvez toucher une créature et puiser dans votre réserve pour soigner autant de points de vie que vous le désirez, sans dépasser le nombre de points dans votre réserve bien entendu.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-sens-divin', 'Sens divin', 'classe', 'Paladin', NULL, 1, 'Une forte présence maléfique éveille vos sens, comme une odeur nocive, et un bien puissant fait résonner dans vos oreilles une musique céleste. Par une action, vous pouvez éveiller votre conscience pour détecter de telles forces. Jusqu''à la fin de votre prochain tour, vous connaissez l''emplacement de toute créature céleste, fiélon ou mort-vivante dans un rayon de 18 mètres autour de vous, et qui ne se trouve pas derrière un abri total. Vous connaissez le type (céleste, fiélon ou mort-vivant) et le nombre de tous les êtres dont vous sentez la présence, mais pas leur identité (le vampire comte Strahd von Zarovich, par exemple). Dans ce même rayon, vous détectez également la présence d''un lieu ou d''un objet qui a été consacré ou profané, comme avec le sort sanctification. Vous pouvez utiliser cette capacité un nombre de fois égal à 1 + votre modificateur de Charisme. Lorsque vous terminez un repos long, vous récupérez toutes les utilisations dépensées.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-arme-a-deux-mains', 'Arme à deux mains', 'classe', 'Paladin', NULL, 2, 'Lorsque vous obtenez 1 ou 2 à un dé de dégâts lors d''une attaque que vous effectuez avec une arme de corps à corps que vous tenez avec vos deux mains, vous pouvez relancer le dé et obligatoirement prendre le nouveau résultat, même si celui-ci est un 1 ou un 2. L''arme doit avoir la propriété à deux mains ou polyvalente pour octroyer cet avantage.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-chatiment-divin', 'Châtiment divin', 'classe', 'Paladin', NULL, 2, 'À partir du niveau 2, quand vous touchez une créature avec une arme de corps à corps, vous pouvez utiliser n''importe quel emplacement de sort (de paladin ou autre) pour châtier cette créature et lui infliger des dégâts radiants supplémentaires. Les dégâts supplémentaires infligés sont de 2d8 pour un emplacement de sort de niveau 1, plus 1d8 supplémentaire pour chaque niveau de sort supérieur à 1, jusqu''à un maximum de 5d8. Si la créature est un mort-vivant ou un fiélon, les dégâts augmentent de 1d8, jusqu''à un maximum de 6d8.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-defense', 'Défense', 'classe', 'Paladin', NULL, 2, 'Si vous portez une armure, vous obtenez un bonus de +1 à la CA.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-duel', 'Duel', 'classe', 'Paladin', NULL, 2, 'Lorsque vous attaquez avec une arme de corps à corps dans une main et aucune autre arme, vous obtenez un bonus de +2 aux dégâts avec cette arme.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-incantation', 'Incantation', 'classe', 'Paladin', NULL, 2, 'Au niveau 2, vous avez appris à tirer parti de la magie divine à travers la méditation et la prière pour lancer des sorts comme un clerc le ferait.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-protection', 'Protection', 'classe', 'Paladin', NULL, 2, 'Quand une créature que vous pouvez voir attaque une cible autre que vous-même et qui se trouve à 1,50 mètre ou moins de vous, vous pouvez utiliser votre réaction pour imposer un désavantage à son jet d''attaque. Vous devez pour cela porter un bouclier.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-style-de-combat', 'Style de combat', 'classe', 'Paladin', NULL, 2, 'Au niveau 2, vous adoptez un style particulier de combat qui sera votre spécialité. Choisissez l''une des options suivantes. Vous ne pouvez pas prendre une option de style de combat plus d''une fois, même si vous obtenez plus tard la possibilité de choisir un nouveau style.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-serment-de-devotion-arme-sacree', 'Arme sacrée', 'classe', 'Paladin', 'Serment de Dévotion', 3, 'Au prix d''une action, vous pouvez imprégner l''arme que vous tenez avec d''énergie positive, utilisant votre Conduit divin. Durant 1 minute, vous ajoutez votre modificateur de Charisme à vos jets d''attaque faits avec cette arme (minimum +1) et l''arme émet une lumière vive dans un rayon de 6 mètres et une lumière faible sur 6 mètres supplémentaires. Si l''arme n''est pas déjà magique, elle le devient pendant la durée du sort. Vous pouvez arrêter cet effet lors de votre tour dans le cadre d''une autre action. Si vous ne tenez plus ou ne portez plus cette arme, ou si vous êtes inconscient, l''effet prend fin.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-conduit-divin', 'Conduit divin', 'classe', 'Paladin', NULL, 3, 'Votre serment vous permet de canaliser de l''énergie divine qui alimente des effets magiques. Chaque Conduit divin proposé par votre serment en détaille les options d''utilisation. Quand vous utilisez votre Conduit divin, vous choisissez quelle option vous voulez utiliser. Un repos court ou long est nécessaire pour pouvoir utiliser un Conduit divin de nouveau. Certains effets de Conduit divin nécessitent des jets de sauvegarde. Quand vous utilisez ce type d''effet, le DD est égal au DD pour résister à vos sorts.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-serment-de-devotion-renvoi-des-impies', 'Renvoi des impies', 'classe', 'Paladin', 'Serment de Dévotion', 3, 'Au prix d''une action, vous présentez votre symbole sacré en psalmodiant une prière contre les morts-vivants ou les fiélons, utilisant votre Conduit divin.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-sante-divine', 'Santé divine', 'classe', 'Paladin', NULL, 3, 'À partir du niveau 3, la magie divine qui coule en vous vous immunise contre les maladies.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-serment-sacre', 'Serment sacré', 'classe', 'Paladin', NULL, 3, 'Au niveau 3, vous prêtez un serment qui vous lie en tant que paladin pour l''éternité. Jusque-là, vous étiez dans une phase préparatoire, engagé dans la voie, mais sans avoir encore prêté serment. Maintenant, vous devez choisir entre le serment de dévotion, le serment des Anciens ou le serment de vengeance. Votre choix vous accorde des capacités au niveau 3, puis aux niveaux 7, 15 et 20. Ces capacités comprennent des sorts de serment et la capacité de Conduit divin.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-sorts-de-serment', 'Sorts de serment', 'classe', 'Paladin', NULL, 3, 'Votre serment vous permet d''accéder à des sorts spécifiques détaillés dans la description du serment. Une fois que vous avez accès à un sort de serment, ce sort est constamment préparé et ne compte pas dans le total de sorts que vous pouvez préparer chaque jour. Si vous gagnez un sort de serment qui n''est pas dans la liste des sorts de paladin, ce sort sera tout de même considéré comme étant un sort de paladin pour vous.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-amelioration-de-caracteristiques', 'Amélioration de caractéristiques', 'classe', 'Paladin', NULL, 4, 'Vous pouvez augmenter une valeur de caractéristique de votre choix de +2, ou bien augmenter deux valeurs de caractéristique de votre choix de +1. Vous ne pouvez cependant pas augmenter une caractéristique au-delà de 20 par ce biais. Vous pouvez le refaire aux niveaux 8, 12, 16 et 19.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-attaque-supplementaire', 'Attaque supplémentaire', 'classe', 'Paladin', NULL, 5, 'Vous pouvez attaquer deux fois, au lieu d''une seule, chaque fois que vous réalisez l''action Attaquer durant votre tour.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-aura-de-protection', 'Aura de protection', 'classe', 'Paladin', NULL, 6, 'Si vous ou une créature alliée située à 3 mètres ou moins de vous doit effectuer un jet de sauvegarde, la créature gagne un bonus égal à votre modificateur de Charisme (minimum +1). Vous devez être conscient pour accorder ce bonus. Au niveau 18, le rayon de l''aura passe à 9 mètres.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-aura-de-devotion', 'Aura de dévotion', 'classe', 'Paladin', NULL, 7, 'À partir du niveau 7, vous et toutes créatures amicales à 3 mètres ou moins de vous ne peuvent être charmées tant que vous êtes conscient. Au niveau 18, le rayon de l''aura passe à 9 mètres.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-aura-de-courage', 'Aura de courage', 'classe', 'Paladin', NULL, 10, 'Vous et toutes créatures amicales situées à 3 mètres ou moins de vous ne pouvez être effrayés tant que vous êtes conscient. Au niveau 18, le rayon de l''aura passe à 9 mètres.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-chatiment-divin-ameliore', 'Châtiment divin amélioré', 'classe', 'Paladin', NULL, 11, 'Vous êtes tellement imprégné de vertus que toutes vos armes de corps à corps portent la puissance divine en elles. Lorsque vous touchez avec une arme de corps à corps, la créature cible subit 1d8 dégâts radiants supplémentaires.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-contact-purificateur', 'Contact purificateur', 'classe', 'Paladin', NULL, 14, 'Vous pouvez utiliser votre action pour mettre fin à un sort sur vous ou une créature consentante que vous touchez. Vous pouvez utiliser cette capacité un nombre de fois égal à votre modificateur de Charisme (minimum 1) entre deux repos long.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-purete-de-l-esprit', 'Pureté de l''esprit', 'classe', 'Paladin', NULL, 15, 'À partir du niveau 15, vous êtes en permanence sous l''effet d''un sort de protection contre le mal et le bien.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('paladin-nimbe-sacre', 'Nimbe sacré', 'classe', 'Paladin', NULL, 20, 'Au niveau 20, au prix d''une action, vous pouvez diffuser une lumière brillante semblable à celle du soleil. Pendant 1 minute, une lumière vive s''échappe de vous sur un rayon de 9 mètres, et une lumière faible sur 9 mètres supplémentaires. Quand une créature ennemie commence son tour dans la zone de lumière vive, elle subit 10 points de dégâts radiants. De plus, pendant cette durée, vous avez un avantage à vos jets de sauvegarde contre les sorts que les fiélons ou les morts-vivants jettent. Une fois cette capacité utilisée, vous devez terminer un repos long pour pouvoir l''utiliser de nouveau.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-ennemi-jure', 'Ennemi juré', 'classe', 'Rôdeur', NULL, 1, 'À partir du niveau 1, vous avez des compétences significatives pour pister, chasser et même communiquer avec un certain type d''ennemi. Choisissez un type d''ennemi juré : aberrations, artificiels, bêtes, célestes, dragons, élémentaires, fées, fiélons, géants, monstruosités, morts-vivants, plantes ou vases. Sinon, vous pouvez sélectionner deux races d''humanoïde (comme gnolls et orcs) comme ennemis favoris. Vous avez un avantage aux jets de Sagesse (Survie) pour pister vos ennemis favoris, ainsi qu''aux jets d''Intelligence permettant de se rappeler des informations sur eux.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-explorateur-ne', 'Explorateur-né', 'classe', 'Rôdeur', NULL, 1, 'Vous êtes particulièrement familier avec un type de milieu naturel et êtes apte à voyager et à survivre dans ces régions. Choisissez un type de terrain favori : arctique, désert, forêt, littoral, marais, montagne, plaine ou Outreterre. Lorsque vous faites un jet d''Intelligence ou de Sagesse lié à votre terrain favori, votre bonus de maîtrise est doublé si vous utilisez une compétence que vous maîtrisez. Lors d''un voyage d''une heure ou plus dans votre terrain favori, vous obtenez les avantages suivants : le terrain difficile ne ralentit pas le voyage de votre groupe; votre groupe ne peut pas se perdre, sauf par des moyens magiques; même lorsque vous êtes engagé dans une autre activité tout en voyageant (comme la recherche de nourriture, la navigation ou le pistage), vous restez alerte face au danger; si vous voyagez seul, vous pouvez vous déplacer furtivement à un rythme normal; lorsque vous cherchez de la nourriture, vous en trouvez deux fois plus que normalement; lorsque vous pistez d''autres créatures, vous découvrez aussi leur nombre exact, leurs tailles, et depuis combien de temps elles sont passées dans la zone.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-incantation', 'Incantation', 'classe', 'Rôdeur', NULL, 2, 'Au moment où vous atteignez le niveau 2, vous avez appris à utiliser l''essence magique de la nature pour lancer des sorts, tout comme le fait un druide.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-style-de-combat', 'Style de combat', 'classe', 'Rôdeur', NULL, 2, 'Au niveau 2, vous adoptez un style particulier de combat qui sera votre spécialité.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-style-de-combat-archerie', 'Style de combat : Archerie', 'classe', 'Rôdeur', NULL, 2, 'Vous obtenez un bonus de +2 aux jets d''attaque avec une arme à distance.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-style-de-combat-combat-a-deux-armes', 'Style de combat : Combat à deux armes', 'classe', 'Rôdeur', NULL, 2, 'Lorsque vous vous engagez dans un combat avec deux armes en mains, vous pouvez ajouter votre modificateur de caractéristique aux dégâts de la seconde attaque.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-style-de-combat-defense', 'Style de combat : Défense', 'classe', 'Rôdeur', NULL, 2, 'Si vous portez une armure, vous obtenez un bonus de +1 à la CA.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-style-de-combat-duel', 'Style de combat : Duel', 'classe', 'Rôdeur', NULL, 2, 'Lorsque vous attaquez avec une arme de corps à corps dans une main et aucune autre arme, vous obtenez un bonus de +2 aux dégâts avec cette arme.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-chasseur-briseur-de-hordes', 'Briseur de hordes', 'classe', 'Rôdeur', 'Chasseur', 3, 'Une fois à chacun de vos tours, lorsque vous faites une attaque avec une arme, vous pouvez faire une autre attaque avec la même arme contre une créature différente qui se situe à 1,50 mètre ou moins de la cible initiale et à portée de votre arme.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-chasseur-tueur-de-colosses', 'Tueur de colosses', 'classe', 'Rôdeur', 'Chasseur', 3, 'Votre ténacité peut user les ennemis les plus puissants. Quand vous touchez une créature lors d''une attaque avec une arme, la créature prend 1d8 dégâts supplémentaires si elle est sous son maximum de points de vie. Vous ne pouvez infliger ces dégâts supplémentaires qu''une fois par tour.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-chasseur-tueur-de-geants', 'Tueur de géants', 'classe', 'Rôdeur', 'Chasseur', 3, 'Quand une créature, de taille G ou supérieure et située à 1,50 mètre ou moins de vous, vous touche ou vous manque lors d''une attaque, vous pouvez utiliser votre réaction pour attaquer cette créature immédiatement après son attaque, à condition que vous puissiez voir la créature.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-vigilance-primitive', 'Vigilance primitive', 'classe', 'Rôdeur', NULL, 3, 'À partir du niveau 3, vous pouvez utiliser votre action et dépenser un emplacement de sort de rôdeur afin de concentrer votre attention sur la région autour de vous. Pour 1 minute par niveau d''emplacement de sort que vous dépensez, vous pouvez sentir si les types de créatures suivants sont présents à 1,5 kilomètre de vous (ou jusqu''à 9 kilomètres si vous êtes dans votre terrain favori) : aberrations, célestes, dragons, élémentaires, fées, démons et morts-vivants. Cette capacité ne révèle pas l''emplacement ou le nombre des créatures.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-amelioration-de-caracteristiques', 'Amélioration de caractéristiques', 'classe', 'Rôdeur', NULL, 4, 'Au niveau 4, puis par la suite aux niveaux 8, 12, 16 et 19, vous pouvez augmenter une valeur de caractéristique de votre choix de +2, ou bien augmenter deux valeurs de caractéristique de votre choix de +1. Vous ne pouvez cependant pas augmenter une caractéristique au-delà de 20 par ce biais.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-attaque-supplementaire', 'Attaque supplémentaire', 'classe', 'Rôdeur', NULL, 5, 'À partir du niveau 5, vous pouvez attaquer deux fois, au lieu d''une seule, chaque fois que vous réalisez l''action Attaquer durant votre tour.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-chasseur-defense-contre-les-attaques-multiples', 'Défense contre les attaques multiples', 'classe', 'Rôdeur', 'Chasseur', 7, 'Quand une créature vous touche lors d''une attaque, vous gagnez un bonus de +4 à la CA contre toutes les attaques ultérieures effectuées par cette créature jusqu''à la fin de votre prochain tour.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-chasseur-echapper-a-la-horde', 'Échapper à la horde', 'classe', 'Rôdeur', 'Chasseur', 7, 'Les attaques d''opportunité effectuées contre vous ont un désavantage.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-foulee-tellurique', 'Foulée tellurique', 'classe', 'Rôdeur', NULL, 8, 'À partir du niveau 8, se déplacer à travers un terrain difficile non magique ne vous coûte pas de mouvement supplémentaire. Vous pouvez également passer à travers des plantes non magiques sans être ralenti et sans subir de dégâts par leurs épines, ou un risque semblable. En outre, vous avez un avantage aux jets de sauvegarde contre les plantes qui sont créés ou manipulés par magie afin d''entraver les mouvements, comme celles créées par le sort enchevêtrement.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-camouflage-naturel', 'Camouflage naturel', 'classe', 'Rôdeur', NULL, 10, 'À partir du niveau 10, vous pouvez passer 1 minute pour vous créer un camouflage. Vous devez avoir accès à de la boue fraîche, de la crasse, des plantes, de la suie et d''autres matériaux naturels avec lesquels vous pouvez créer votre camouflage. Une fois que vous êtes camouflé de cette façon, vous pouvez essayer de vous cacher en vous appuyant contre une surface solide, comme un arbre ou un mur, s''il est au moins aussi grand et aussi large que vous. Vous bénéficiez d''un bonus de +10 aux jets de Dextérité (Discrétion) aussi longtemps que vous restez sans bouger et sans effectuer d''actions. Une fois que vous vous déplacez ou prenez une action ou une réaction, vous devez vous camoufler à nouveau pour regagner cet avantage.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-disparition', 'Disparition', 'classe', 'Rôdeur', NULL, 14, 'À partir du niveau 14, vous pouvez utiliser l''action Se cacher en tant qu''action bonus à votre tour. En outre, vous ne pouvez pas être suivi par des moyens non magiques.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-sens-sauvages', 'Sens sauvages', 'classe', 'Rôdeur', NULL, 18, 'Au niveau 18, vous gagnez un sens surnaturel qui vous aide à combattre les créatures que vous ne pouvez pas voir. Lorsque vous attaquez une créature que vous ne pouvez pas voir, votre incapacité à voir ne vous impose pas un désavantage à vos jets d''attaque contre elle. Vous êtes également au courant de l''emplacement d''une créature invisible dans un rayon de 9 mètres autour de vous, à condition que la créature ne se soit pas cachée vis-à-vis de vous et que vous ne soyez pas aveuglé ou assourdi.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('rodeur-tueur-implacable', 'Tueur implacable', 'classe', 'Rôdeur', NULL, 20, 'Au niveau 20, vous devenez un chasseur hors pair pour vos ennemis. Une fois à chacun de vos tours, vous pouvez ajouter votre modificateur de Sagesse au jet d''attaque ou de dégâts d''une attaque que vous effectuez contre l''un de vos ennemis favoris. Vous pouvez choisir d''utiliser cette capacité avant ou après le jet, mais avant que les effets du jet ne soient appliqués.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('demi-elfe-ascendance-feerique', 'Ascendance féérique', 'race', 'Demi-elfe', NULL, NULL, 'Vous avez un avantage aux jets de sauvegarde contre les effets de charme et la magie ne peut pas vous endormir.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('demi-elfe-polyvalence', 'Polyvalence', 'race', 'Demi-elfe', NULL, NULL, 'Vous gagnez la maîtrise de deux compétences de votre choix.')
on conflict (slug) do update set nom = excluded.nom, type = excluded.type, source = excluded.source, sous_source = excluded.sous_source, niveau = excluded.niveau, description = excluded.description;
insert into features (slug, nom, type, source, sous_source, niveau, description) values ('demi-elfe-vision-dans-le-noir', 'Vision dans le noir', 'race', 'Demi-elfe', NULL, NULL, 'Grâce à votre sang elfe, vous avez une vision supérieure dans le noir et les conditions de faible éclairage. Vous pouvez voir à 18 mètres dans une lumière faible comme vous verriez avec une lumière vive, et dans le noir comme vous verriez avec une lumière faible. Dans le noir, vous ne discernez pas les couleurs, uniquement des nuances de gris.')
