insert into features (slug, nom, type, source, sous_source, niveau, description) values ('draconien-langues', 'Langues', 'race', 'Draconien', NULL, NULL, 'Vous pouvez parler, lire et écrire le commun et le draconique. Le draconique passe pour être l''une des plus anciennes langues et est souvent utilisé dans l''étude de la magie. La langue semble cassante pour la plupart des autres créatures, et comprend de nombreuses consonnes dures et sifflantes.')
