insert into features (slug, nom, type, source, sous_source, niveau, description) values ('tieffelin-ascendance-infernale', 'Ascendance infernale', 'race', 'Tieffelin', NULL, NULL, 'Vous connaissez le sort mineur thaumaturgie. Quand vous atteignez le niveau 3, vous pouvez lancer le sort représailles infernales comme un sort de niveau 2 une fois avec ce trait et regagnez cette capacité lorsque vous terminez un repos long. Quand vous atteignez le niveau 5, vous pouvez lancer le sort ténèbres une fois avec ce trait et regagnez cette capacité lorsque vous terminez un repos long. Le Charisme est votre caractéristique d''incantation pour ces sorts.')
